sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    // If this offer was linked to a lab_test_result
    var labResultId = current.getValue('lab_test_result');
    if (!labResultId) return;

    var labGr = new GlideRecord('x_2223823_apollo_0_lab_test_result');
    if (!labGr.get(labResultId)) return;

    var equipmentAssetId = labGr.getValue('equipment');
    if (!equipmentAssetId) return;

    // Find any planned changes currently in Authorize for this equipment
    var chgGr = new GlideRecord('change_request');
    chgGr.addQuery('state', '-3').addOrCondition('type', 'emergency')
	chgGr.addQuery('cmdb_ci', labGr.equipment.ci.toString());
    chgGr.addQuery('x_2223823_apollo_0_conflicts_resolved', false);
    chgGr.query();

    var conflictService = new x_2223823_apollo_0.ConflictService();

    while (chgGr.next()) {
        var startGdt = new GlideDateTime(chgGr.getValue('start_date'));
        var endGdt = new GlideDateTime(chgGr.getValue('end_date'));
        var remainingConflicts = conflictService.findConflictingLabTests(equipmentAssetId, startGdt, endGdt, chgGr.getValue('x_2223823_apollo_0_hospital'));

        if (remainingConflicts.length === 0) {
            chgGr.setValue('x_2223823_apollo_0_conflict_count', 0);
            chgGr.setValue('x_2223823_apollo_0_conflicts_resolved', true);
            chgGr.work_notes = 'All conflicting patient bookings have been resolved. Change is now clear to move forward.';
            chgGr.update();
        } else {
            chgGr.setValue('x_2223823_apollo_0_conflict_count', remainingConflicts.length);
            chgGr.update();
        }
    }
})(current, previous);
